function $(s,r){return (r||document).querySelector(s)}function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}function clone(v){return JSON.parse(JSON.stringify(v))}function say(m){$('#toast').textContent=m;$('#toast').hidden=false;clearTimeout(say.timer);say.timer=setTimeout(function(){$('#toast').hidden=true},4500)}
function valid(c){if(!c||c.schema!=='hnc.care-template-products/1'||!c.templates||typeof c.templates!=='object'||Array.isArray(c.templates))throw Error('Select an admin mapping backup JSON file.');Object.keys(c.templates).forEach(function(id){var t=c.templates[id];if(!BASE.some(function(b){return b.id===id})||!Array.isArray(t.products)||['all','male','female'].indexOf(t.sex)<0)throw Error('Invalid template '+id);if(t.variants){Object.keys(t.variants).forEach(function(k){if(['male','female'].indexOf(k)<0)throw Error('Invalid pathway');var v=t.variants[k];if(v.sex!==k||!Array.isArray(v.products))throw Error('Invalid '+k+' mapping');if(v.guidance)['02','03','04'].forEach(function(c){if(!Array.isArray(v.guidance.categories[c]))throw Error('Invalid pathway guidance')})})}if(t.guidance){['02','03','04'].forEach(function(k){if(!Array.isArray(t.guidance.categories[k]))throw Error('Invalid guidance section '+k);t.guidance.categories[k].forEach(function(r){if(typeof r.title!=='string'||typeof r.purpose!=='string')throw Error('Invalid guidance entry')})})}});return c}
function status(){var el=$('#status');if(!el)return;if(stored){el.hidden=true;el.className='status';el.textContent='';return}el.hidden=false;el.className='status error';el.textContent='Browser storage unavailable · changes stay in memory; export a backup before closing.'}
function save(next){valid(next);var expected=data.version;next=clone(next);next.version=Math.max(Number(next.version)||0,Number(expected||0)+1);if(parent!==window&&parent.HNCCareBridge){parent.HNCCareBridge.save({config:next,products:products,expectedVersion:expected});}else{var raw=localStorage.getItem(KEY);if(raw&&Number(JSON.parse(raw).version)>Number(expected))throw Error('Care settings changed elsewhere. Reload before saving.');}data=next;try{localStorage.setItem(KEY,JSON.stringify(data));localStorage.setItem(PRODUCT_KEY,JSON.stringify(products));stored=true}catch(e){stored=false}status()}
function load(){data=clone(window.HNC_DEFAULT_CARE);try{if(parent!==window&&parent.HNCCareBridge){var shared=parent.HNCCareBridge.get();if(shared.config)data=valid(shared.config);if(shared.products)products=shared.products;status();return}}catch(e){}try{var raw=localStorage.getItem(KEY);if(raw)data=valid(JSON.parse(raw));var p=localStorage.getItem(PRODUCT_KEY);if(p&&Array.isArray(JSON.parse(p)))products=JSON.parse(p)}catch(e){stored=false}status()}
var laneSelection={};
function pathways(id){if(['01','03','04','27','28','29','30'].indexOf(id)>=0)return ['female'];if(['18','19','20','21','22','23'].indexOf(id)>=0)return ['male'];return ['all','male','female']}
function laneFor(id){return laneSelection[id]||pathways(id)[0]}
function mappingFor(id,lane){var root=data.templates[id];if(!root)return null;if(root.variants&&root.variants[lane])return root.variants[lane];if(root.sex==='all'||root.sex===lane)return root;return null}
function effective(b,lane){var t=mappingFor(b.id,lane||laneFor(b.id));return {id:b.id,title:b.title,data:t&&t.guidance?clone(t.guidance):clone(b.data)}}
function allMappings(root){var out=[root];Object.keys(root.variants||{}).forEach(function(k){out.push(root.variants[k])});return out}
function download(name,obj){var text=typeof obj==='string'?obj:JSON.stringify(obj,null,2),blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},1500)}
function openModal(html,mount){var root=$('#modal');root.innerHTML='<div class="modal-back"><section class="modal" role="dialog" aria-modal="true" aria-label="Care editor">'+html+'</section></div>';var m=$('.modal',root);modalClose=function(){root.innerHTML='';modalClose=null};m.querySelectorAll('[data-close]').forEach(function(b){b.onclick=modalClose});if(mount)mount(m,modalClose);var first=m.querySelector('button,input,select,textarea');if(first)first.focus()}
function head(t,sub){return '<div class="modal-head"><div><p class="eyebrow">'+esc(sub)+'</p><h2>'+esc(t)+'</h2></div><button class="close" type="button" data-close aria-label="Close">×</button></div>'}
