function renderTemplates(){ $('#main').innerHTML=hero('Intelligence, curated.<br><em>Care, connected.</em>','A) Map products and assessment guidance. B) Preview the complete prescription. Choose separate male and female pathways where applicable. Products and guidance can be transferred to the frontend with a mapping backup.')+'<div class="toolbar"><label class="sr" for="search">Search templates</label><input id="search" type="search" placeholder="Search 37 care templates…" value="'+esc(query)+'"><button class="gold" id="export-top">Export mapping backup</button></div><div id="cards" class="grid"></div><p class="footer">Template configuration is educational and does not create an issued prescription.</p>';$('#search').oninput=function(){query=this.value;cards()};$('#export-top').onclick=function(){download('HairsnCares-Care-Product-Mappings.json',{schema:'hnc.offline-admin-backup/2',config:data,products:products})};cards()}
